.wrapper {
    width: 60%;
    margin: 0 auto;
    height: 100%;
    display: flex;
    flex-direction: column;
    gap: var(--gap);
}
.parsed .wrapper {
    width: 100%;
}
.logo {
    margin: auto;
}
